-- Catálogo aprobado: tarifas por oferta; no altera tipos, habitaciones ni reservas anteriores.
CREATE TABLE catalogo_configuraciones(clave varchar(10) PRIMARY KEY,tipo_habitacion_id bigint NOT NULL REFERENCES tipos_habitacion(id));
CREATE TABLE catalogo_ofertas(slug varchar(80) PRIMARY KEY,tipo_habitacion_id bigint NOT NULL REFERENCES tipos_habitacion(id),precio_base numeric(12,2) NOT NULL CHECK(precio_base>0),contenido jsonb NOT NULL,orden int NOT NULL);
CREATE TABLE catalogo_oferta_habitaciones(slug varchar(80) REFERENCES catalogo_ofertas(slug),habitacion_id bigint REFERENCES habitaciones(id),evidencia text NOT NULL,PRIMARY KEY(slug,habitacion_id));
CREATE TABLE reserva_ofertas(reserva_id bigint PRIMARY KEY REFERENCES reservas(id),slug varchar(80) NOT NULL REFERENCES catalogo_ofertas(slug),contenido jsonb NOT NULL);
-- Los datos del catálogo se arman sobre los tipos y habitaciones ficticios de db/demo (V6).
-- Sin ellos (sin el perfil demo, como en producción) la migración solo crea el esquema.
DO $$ BEGIN
IF EXISTS(SELECT 1 FROM tipos_habitacion) THEN
INSERT INTO catalogo_configuraciones VALUES ('E2',3),('SU2',2);
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Deluxe King','Una cama king.',2,580,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'D2',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Deluxe King Triple','Una cama king; distribución para el tercer huésped pendiente de acreditar.',3,580,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'D3',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Superior King','Una cama king; distribución para el tercer huésped pendiente de acreditar.',3,500,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'S3',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Familiar Dos Camas','Dos camas; medidas pendientes de acreditar.',4,720,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'F4',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Familiar Cinco','Dos camas; medidas y distribución pendientes de acreditar.',5,720,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'F5',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Premium Cuatro','Dos camas; medidas pendientes de acreditar.',4,790,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'P4',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Deluxe King Sofá','Una cama king y un sofá cama.',3,580,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'DT3',id FROM nuevo;
WITH nuevo AS (INSERT INTO tipos_habitacion(nombre,descripcion,capacidad,precio_base,ajuste_fin_semana_pct) VALUES ('Premium Cinco','Dos camas y un sofá; medidas pendientes de acreditar.',5,790,0) RETURNING id) INSERT INTO catalogo_configuraciones SELECT 'P5',id FROM nuevo;
